import { useClaims } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { personSplit, useRates } from '../rates/rates';
import { useDueRules, useSettings } from '../settings/settings';
import { personOverdue } from '../overdue/overdue';
import { band, score } from './score';

// A person's score: their settled counting figures / 100, minus 5 per overdue counting claim, rounded half to even.
export function PersonScore({ person }: { person: Person }) {
  return <td data-testid="person-score">{usePersonScore(person)}</td>;
}

// A person's band by the sheet's score thresholds: HIGH, MID or LOW; blank while either threshold is blank.
export function PersonBand({ person }: { person: Person }) {
  const settings = useSettings().data;
  const value = usePersonScore(person);
  return <td data-testid="person-band">{band(value, settings?.scoreMid ?? '', settings?.scoreHigh ?? '')}</td>;
}

function usePersonScore(person: Person): string {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  const holds = liveHolds(person, rules.today);
  const { settled } = personSplit(claims, rates, person.grades, holds, rules);
  const { count } = personOverdue(claims, rates, person.grades, holds, rules);
  return score(settled, count);
}
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonBand, PersonScore } from './PersonScore';

export const contributions = [
  PersonColumnHeads.fill({ order: 17.5, Component: () => <th>Score</th> }),
  PersonColumns.fill({ order: 17.5, Component: PersonScore }),
  PersonColumnHeads.fill({ order: 17.6, Component: () => <th>Band</th> }),
  PersonColumns.fill({ order: 17.6, Component: PersonBand }),
];
/**
 * A person's score: their settled figures (in cents) divided by 100, minus 5 for every overdue claim of theirs that
 * counts, rounded half to even to a whole number. Worked in whole cents so it is exact: (cents − 50000 × overdue) / 10000.
 */
export function score(settled: string, overdueCount: number): string {
  const value = Math.round(Number(settled) * 100) - 50000 * overdueCount;
  const whole = Math.floor(Math.abs(value) / 10000);
  const rest = Math.abs(value) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && whole % 2 === 1);
  const result = Math.sign(value) * (whole + (up ? 1 : 0));
  return String(result === 0 ? 0 : result);
}

/** A score's band: HIGH at or above the high threshold, MID at or above the mid one, else LOW; '' while either is blank. */
export function band(value: string, mid: string, high: string): string {
  if (mid === '' || high === '') return '';
  const n = Number(value);
  if (n >= Number(high)) return 'HIGH';
  if (n >= Number(mid)) return 'MID';
  return 'LOW';
}
