package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.Map;

/**
 * A sheet's figures at one moment: each person's claimed, due-total and overdue-total (by person id, in the
 * order of the list) and the sheet's claimed-total, due-total and overdue-total, each as shown (two decimals; a due-total may be n/a),
 * and the sheet's alert threshold (null: off).
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
        BigDecimal alertThreshold) {

    /** Whether the due-total as shown (n/a or null: none) is above the threshold (null: off). */
    public static boolean above(String dueTotal, BigDecimal threshold) {
        return threshold != null && dueTotal != null && !dueTotal.equals("n/a")
                && new BigDecimal(dueTotal).compareTo(threshold) > 0;
    }

    /** A person's name and figures. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {

        /** Whether the figures are the same as the other's, whatever the name. */
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }
}
package net.officefloor.hq.app.rollup;

import java.util.Map;
import net.officefloor.hq.app.Audit;

/**
 * The lines that follow a change's own records: one ROLLUP line per person whose figures it moved (a person new to the
 * sheet counts as moved), in the order of the list, then a TOTALS line when the sheet's totals moved, then one ALERT
 * line per person whose due-total went from at or below the sheet's alert threshold (or no due-total) to above it, in the
 * order of the list.
 */
public final class RollupLines {

    private RollupLines() {
    }

    /** Records the ROLLUP and TOTALS lines for the sheet's figures moving from {@code was} to {@code now}. */
    public static void record(Rollup was, Rollup now, String sheetId, String user, Audit audit) {
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
            Rollup.Figures figures = entry.getValue();
            if (!figures.sameAs(was.people().get(entry.getKey()))) {
                audit.record("ROLLUP" + prefix + " person=" + figures.name() + " claimed=" + figures.claimed()
                        + " due-total=" + figures.dueTotal() + " overdue-total=" + figures.overdueTotal());
            }
        }
        if (!now.claimedTotal().equals(was.claimedTotal()) || !now.dueTotal().equals(was.dueTotal())
                || !now.overdueTotal().equals(was.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + now.claimedTotal() + " due-total="
                    + now.dueTotal() + " overdue-total=" + now.overdueTotal());
        }
        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
            Rollup.Figures figures = entry.getValue();
            Rollup.Figures before = was.people().get(entry.getKey());
            if (Rollup.above(figures.dueTotal(), now.alertThreshold())
                    && !Rollup.above(before == null ? null : before.dueTotal(), now.alertThreshold())) {
                audit.record("ALERT" + prefix + " name=" + figures.name() + " due-total=" + figures.dueTotal());
            }
        }
    }
}
